<?php $page_title='Promotions';require 'includes/header.php';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$vals=['promo_text'=>trim($_POST['promo_text']),'sale_headline'=>trim($_POST['sale_headline']),'sale_percentage'=>trim($_POST['sale_percentage']),'countdown_end'=>trim($_POST['countdown_end']),'promo_active'=>isset($_POST['promo_active'])?'1':'0'];foreach($vals as $k=>$v)$pdo->prepare("INSERT INTO site_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)")->execute([$k,$v]);flash('success','Promotion settings saved.');header('Location: promotions.php');exit;}$settings=[];foreach($pdo->query("SELECT setting_key,setting_value FROM site_settings") as $r)$settings[$r['setting_key']]=$r['setting_value'];?>
<div class="page-head"><div><h1>Promotions</h1><p>Homepage promotional banner controls.</p></div></div><div class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="field"><label>Sale headline</label><input class="input" name="sale_headline" value="<?=e($settings['sale_headline']??'Seasonal Sale')?>"></div><div class="form-grid"><div class="field"><label>Sale percentage</label><input class="input" name="sale_percentage" value="<?=e($settings['sale_percentage']??'20')?>"></div><div class="field"><label>Countdown end</label><input class="input" type="datetime-local" name="countdown_end" value="<?=e($settings['countdown_end']??'')?>"></div></div><div class="field"><label>Promotional text</label><textarea name="promo_text" rows="4"><?=e($settings['promo_text']??'Seasonal edit · Up to 20% off selected pieces')?></textarea></div><label><input type="checkbox" name="promo_active" <?=$settings['promo_active']??'1'?'checked':''?>> Active</label><br><br><button class="btn">Save promotion</button></form></div><?php require 'includes/footer.php';?>
